choose.when:
SELECT #{statusValid} statusValid, T1.TOTLE_TRADE_ID busiCode, T1.CCY, T3.PA_BUSS_TYPE, T1.PS cashType, T1.PORTFOLIO_ID,
T1.CHL_ID chlId, TC4.FINPROD_NAME channelName,
FPD.COLLECT_TYPE collectType, T1.FEE_AMT - IFNULL(T5.FEE_AMT, 0) channelFee, IFNULL(T1.FPRICE_AMT,T1.TRADE_AMT) tradeAmtReal, CASE WHEN T1.CHL_ID IS NULL THEN 0 ELSE 1 END channel,
fprod_type.TYPE_6 assetType, T1.FINPROD_ID, T4.FINPROD_MARKET_ID, T4.FINPROD_NAME finprodMarketName, T1.VDATE vdateProd, T1.MDATE mdateProd, fccr.BASIS, T4.VDATE, T4.MDATE, T4.ENTRUSTER, T3.RATE*100 earlyWithdrawalRate,
fccr.YIELD*100 yield,
T5.FEE_AMT,
T3.THEORY_INT, T3.THEORY_AMT fpriceAmt,
T3.REMAIN_PRIN_AMT remainPrinAmt,
T3.THEORY_PRIN earlyWithdrawalAmt, T1.INT_AMT, T1.TRADE_AMT, T1.TRADE_DATE tradeDate, fccrt_2.YIELD*100 loadRate， tdta.INT_SETT_TYPE FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN TRD_TRADE_FEE_DETAIL T5 on T5.TRADE_ID = T1.TOTLE_TRADE_ID
LEFT JOIN FIN_PRODUCT TC4 ON T1.CHL_ID = TC4.FINPROD_ID
LEFT JOIN FIN_PRODUCT_ADD FPD ON TC4.FINPROD_ID=FPD.FINPROD_ID
LEFT JOIN FIN_PRODUCT_TYPE fprod_type on fprod_type.FINPROD_ID = T1.FINPROD_ID
LEFT JOIN FIN_CASH_INFO fcinfo on fcinfo.FINPROD_ID = T1.FINPROD_ID and fcinfo.CASH_TYPE_2 = #{CASH_TYPE_2_C08}
LEFT JOIN FIN_CASH_CALC_RULE fccr on fccr.CASH_ID = fcinfo.CASH_ID and fccr.EFF_DATE <= T1.MDATE and not EXISTS ( select 1 from FIN_CASH_CALC_RULE fccr2 where fccr2.CASH_ID =fccr.CASH_ID and fccr2.EFF_DATE > fccr.EFF_DATE and fccr2.EFF_DATE <= T1.MDATE )
LEFT JOIN FIN_CASH_INFO fcinfo2 on fcinfo2.FINPROD_ID = T1.FINPROD_ID and fcinfo2.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
LEFT JOIN FIN_CASH_CALC_RULE fccrt_2 on fccrt_2.CASH_ID = fcinfo2.CASH_ID and fccrt_2.EFF_DATE <= T1.MDATE and not EXISTS ( select 1 from FIN_CASH_CALC_RULE fccr_2 where fccr_2.CASH_ID =fccrt_2.CASH_ID and fccr_2.EFF_DATE > fccrt_2.EFF_DATE and fccr_2.EFF_DATE <= T1.MDATE ) left join TRD_DEAL_TOTAL_ADD tdta on tdta.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID WHERE T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF07}
and T1.TRADE_STATUS = #{TRADE_STATUS01}
and T1.TOTLE_TRADE_ID = #{busiCode}
and T1.TRADE_STATUS = #{TRADE_STATUS01} and T1.IS_CANCEL = #{YESNO_Y} and T1.TOTLE_TRADE_ID = #{pTradeId}

mapper.select:
  SELECT
    count( 1 )
FROM
    TRD_PRODUCT_DEAL
    where TRADE_DATE >= STR_TO_DATE(#{tradeDate},'%Y-%m-%d')

           and  FINPROD_ID  = #{finprodId}


            and PS  = #{ps}


            and IS_CLEAN = #{yes}


            and IS_CANCEL != #{yes}


            and TRADE_STATUS = #{tradeStatus}

	    select TRADE_ID from TRD_PRODUCT_DEAL
		where TOTLE_TRADE_ID in
		(SELECT TOTLE_TRADE_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL
		WHERE P_TOTLE_TRADE_ID = #{totleTradeId}
		)
		and PS = 'T23'
		and TRADE_STATUS = '01'

		union all
		/* 提前支取 */
		select TRADE_ID from TRD_PRODUCT_DEAL
		where TOTLE_TRADE_ID = #{totleTradeId}
    	and ps = 'T38'
    	and TRADE_STATUS = '01'
